+
+  it('a cleanup hook that itself fails does not turn a rejection into a throw', () => {
+    const { driver } = freshGoldenSource();
+    const targetPath = path.join(dir, 'migrated.arq');
+
+    expect(() =>
+      migrateArqfsCopyOnWrite(
+        driver,
+        targetPath,
+        createNodeArqfsDriver,
+        () => {
