+  try {
+    fsyncPath(resolvedReplacement);
+  } catch (error) {
+    return {
+      status: 'rejected',
+      code: 'ARQ_SWAP_FAILED',
+      reason: `could not flush replacement: ${error instanceof Error ? error.message : String(error)}`,
+      canonicalPreserved: true,
+    };
+  }
