+  );
+  try {
+    execFileSync('npx', ['vitest', 'run', testFilePath, '--coverage=false'], {
+      cwd: repoRoot,
+      stdio: 'inherit',
+    });
+  } finally {
+    rmSync(testFilePath, { force: true });
+  }
+  return {
+    goodPath: path.join(dir, 'good.arq'),
+    truncatedPath: path.join(dir, 'truncated.arq'),
+    otherPath: path.join(dir, 'other.sqlite3'),
+  };
