+  console.log(`\nSaved to ${path.relative(repoRoot, outPath)}`);
+
+  if (!report.ok) {
+    process.exitCode = 1;
+  }
+}
+
+main().catch((error) => {
+  console.error(error);
+  process.exitCode = 1;
+});

